import java.util.*;

class Solution {
    public boolean isPathCrossing(String path) {
        Set<String> visited = new HashSet<>();
        int x = 0, y = 0;
        visited.add(x + "," + y);
        for (char step : path.toCharArray()) {
            if (step == 'N') y++;
            else if (step == 'S') y--;
            else if (step == 'E') x++;
            else x--;
            if (!visited.add(x + "," + y)) return true;
        }
        return false;
    }
}
